25	GraphOperationBuilder &GraphOperationBuilder::SetInputOutput(const std::vector<std::string> &inTensorNames,
26	                                                             const std::vector<std::string> &outTensorNames)
27	{
28	    uint32_t id = 0;
29	    size_t inTensorNum = inTensorNames.size();
30	    if (inTensorNum > MAX_TENSOR_NUM) {
31	        throw std::runtime_error("inTensor num should be <= 256, but get " + std::to_string(inTensorNum));
32	    }
33	    for (const std::string &inTensorName : inTensorNames) {
34	        inTensorIds_[inTensorName] = id++;
35	    }
36	    size_t outTensorNum = outTensorNames.size();
37	    if (outTensorNum > MAX_TENSOR_NUM) {
38	        throw std::runtime_error("outTensor num should be <= 256, but get " + std::to_string(outTensorNum));
39	    }
40	    for (const std::string &outTensorName : outTensorNames) {
41	        outTensorIds_[outTensorName] = id++;
42	    }
43	    graphParam_.inTensorNum = static_cast<uint32_t>(inTensorNum);
44	    graphParam_.outTensorNum = static_cast<uint32_t>(outTensorNum);
45	    return *this;
