48	GraphOperationBuilder &GraphOperationBuilder::AddOperation(OperationWrapper &opWrapper,
49	                                                           const std::vector<std::string> &inTensorNames,
50	                                                           const std::vector<std::string> &outTensorNames)
51	{
52	    atb::Operation *rawPtr = opWrapper.ReleaseOperation();
53	    if (rawPtr == nullptr) {
54	        throw std::runtime_error("add operation is null.");
55	    }
56	    Node node;
57	    node.operation = rawPtr;
58	    node.inTensorIds.resize(0);
59	    node.outTensorIds.resize(0);
60	    node.inTensorReshapeFuncs.resize(0);
61	    for (const std::string &inTensorName : inTensorNames) {
62	        node.inTensorIds.push_back(GetTensorId(inTensorName));
63	        if (internalTensorNum_ > MAX_TENSOR_NUM) {
64	            throw std::runtime_error("internalTensor num should be <= 256, but get " +
65	                                     std::to_string(internalTensorNum_));
66	        }
67	        if (reshapedTensorIds_.find(inTensorName) != reshapedTensorIds_.end()) {
68	            node.inTensorReshapeFuncs.push_back(reshapedTensorIds_[inTensorName].second);
69	        } else {
70	            node.inTensorReshapeFuncs.push_back(nullptr);
71	        }
72	    }
73	    for (const std::string &outTensorName : outTensorNames) {
74	        node.outTensorIds.push_back(GetTensorId(outTensorName));
75	        if (internalTensorNum_ > MAX_TENSOR_NUM) {
76	            throw std::runtime_error("internalTensor num should be <= 256, but get " +
77	                                     std::to_string(internalTensorNum_));
78	        }
79	    }
80	    graphParam_.nodes.push_back(node);
81	    return *this;
82	}
