84	GraphOperationBuilder &GraphOperationBuilder::Reshape(const std::string &srcTensorName,
85	                                                      const ReshapeHandler &reshapeHandler,
86	                                                      const std::string &reshapedTensorName)
87	{
88	    atb::ReshapeFunc reshapeFunc = [reshapeHandler](const Dims &oldShape, Dims &newShape) {
89	        std::vector<int64_t> oldShapeVec(oldShape.dimNum);
90	        for (size_t i = 0; i < oldShape.dimNum; ++i) {
91	            oldShapeVec[i] = oldShape.dims[i];
92	        }
93	        std::vector<int64_t> newShapeVec = reshapeHandler(oldShapeVec);
94	        ATB_LOG(INFO) << "oldShapeVec: " << oldShapeVec << ", newShapeVec: " << newShapeVec;
95	        newShape.dimNum = newShapeVec.size();
96	        for (uint64_t i = 0; i < newShape.dimNum; ++i) {
97	            newShape.dims[i] = newShapeVec[i];
98	        }
99	    };
100	    reshapedTensorIds_[reshapedTensorName] = {GetTensorId(srcTensorName), reshapeFunc};
101	    return *this;
102	}
