112	    if (inTensorIds_.find(tensorName) != inTensorIds_.end()) {
113	        return inTensorIds_[tensorName];
114	    } else if (outTensorIds_.find(tensorName) != outTensorIds_.end()) {
115	        return outTensorIds_[tensorName];
116	    } else if (reshapedTensorIds_.find(tensorName) != reshapedTensorIds_.end()) {
117	        return reshapedTensorIds_[tensorName].first;
118	    } else if (internalTensorIds_.find(tensorName) != internalTensorIds_.end()) {
119	        return internalTensorIds_[tensorName];
120	    } else {
121	        uint32_t internalTensorId = inTensorIds_.size() + outTensorIds_.size() + internalTensorNum_++;
122	        internalTensorIds_[tensorName] = internalTensorId;
123	        return internalTensorId;
124	    }
