14	
15	static void CreateInTensorDescs(atb::SVector<atb::TensorDesc> &intensorDescs)
16	{
17	    for (size_t i = 0; i < intensorDescs.size(); i++) {
18	        intensorDescs.at(i).dtype = ACL_FLOAT16;
19	        intensorDescs.at(i).format = ACL_FORMAT_ND;
20	        intensorDescs.at(i).shape.dimNum = 2;
21	        intensorDescs.at(i).shape.dims[0] = 2;
22	        intensorDescs.at(i).shape.dims[1] = 2;
23	    }
24	}
25	
26	static aclError CreateInTensors(atb::SVector<atb::Tensor> &inTensors, atb::SVector<atb::TensorDesc> &intensorDescs)
27	{
28	    std::vector<char> zeroData(8, 0); // 一段全0的hostBuffer
29	    int ret;
30	    for (size_t i = 0; i < inTensors.size(); i++) {
31	        inTensors.at(i).desc = intensorDescs.at(i);
32	        inTensors.at(i).dataSize = atb::Utils::GetTensorSize(inTensors.at(i));
33	        ret = aclrtMalloc(&inTensors.at(i).deviceData, inTensors.at(i).dataSize,
34	                          ACL_MEM_MALLOC_HUGE_FIRST); // 分配NPU内存
35	        if (ret != 0) {
36	            std::cout << "alloc error!";
37	            return ret;
38	        }
39	        // 拷贝CPU内存到NPU侧
40	        ret = aclrtMemcpy(inTensors.at(i).deviceData, inTensors.at(i).dataSize, zeroData.data(), zeroData.size(),
41	                          ACL_MEMCPY_HOST_TO_DEVICE);
42	        if (ret != 0) {
43	            std::cout << "memcpy error!";
44	        }
45	    }
46	    return ret;
47	}
48	
49	// 设置各个outtensor并且为outtensor分配内存空间，同intensor设置
50	static aclError CreateOutTensors(atb::SVector<atb::Tensor> &outTensors, atb::SVector<atb::TensorDesc> &outtensorDescs)
51	{
52	    int ret;
53	    for (size_t i = 0; i < outTensors.size(); i++) {
54	        outTensors.at(i).desc = outtensorDescs.at(i);
55	        outTensors.at(i).dataSize = atb::Utils::GetTensorSize(outTensors.at(i));
56	        ret = aclrtMalloc(&outTensors.at(i).deviceData, outTensors.at(i).dataSize, ACL_MEM_MALLOC_HUGE_FIRST);
57	        if (ret != 0) {
58	            std::cout << "alloc error!";
59	        }
60	    }
61	    return ret;
62	}
63	
64	static void CreateMiniGraphOperation(atb::GraphParam &opGraph, atb::Operation **operation)
65	{
66	    // 构子图流程
67	    opGraph.inTensorNum = 2;
68	    opGraph.outTensorNum = 1;
69	    opGraph.internalTensorNum = 2;
70	    opGraph.nodes.resize(3);
71	
72	    size_t nodeId = 0;
73	    atb::Node &addNode = opGraph.nodes.at(nodeId++);
74	    atb::Node &addNode2 = opGraph.nodes.at(nodeId++);
75	    atb::Node &addNode3 = opGraph.nodes.at(nodeId++);
76	
77	    atb::infer::ElewiseParam addParam;
78	    addParam.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_ADD;
79	    atb::CreateOperation(addParam, &addNode.operation);
80	    addNode.inTensorIds = {0, 1};
81	    addNode.outTensorIds = {3};
82	
83	    atb::infer::ElewiseParam addParam2;
84	    addParam2.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_ADD;
85	    atb::CreateOperation(addParam2, &addNode2.operation);
86	    addNode2.inTensorIds = {3, 1};
87	    addNode2.outTensorIds = {4};
88	
89	    atb::infer::ElewiseParam addParam3;
90	    addParam3.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_ADD;
91	    CreateOperation(addParam3, &addNode3.operation);
92	    addNode3.inTensorIds = {4, 1};
93	    addNode3.outTensorIds = {2};
94	
95	    atb::CreateOperation(opGraph, operation);
96	}
97	
98	static void CreateGraphOperationWithWREvent(atb::GraphParam &opGraph, atb::Operation **operation, aclrtEvent event)
99	{
100	    opGraph.inTensorNum = 2;
101	    opGraph.outTensorNum = 1;
102	    opGraph.internalTensorNum = 2;
103	    opGraph.nodes.resize(5);
104	
105	    size_t nodeId = 0;
106	    atb::Node &mulNode = opGraph.nodes.at(nodeId++);
107	    atb::Node &waitNode = opGraph.nodes.at(nodeId++);
108	    atb::Node &addNode = opGraph.nodes.at(nodeId++);
109	    atb::Node &graphNode = opGraph.nodes.at(nodeId++);
110	    atb::Node &recordNode = opGraph.nodes.at(nodeId++);
111	
112	    atb::infer::ElewiseParam mulParam;
113	    mulParam.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_MUL;
114	    atb::CreateOperation(mulParam, &mulNode.operation);
115	    mulNode.inTensorIds = {0, 1};
116	    mulNode.outTensorIds = {3};
117	
118	    atb::common::EventParam waitParam;
119	    waitParam.event = event;
120	    waitParam.operatorType = atb::common::EventParam::OperatorType::WAIT;
121	    atb::CreateOperation(waitParam, &waitNode.operation);
122	
123	    atb::GraphParam graphParam;
124	    CreateMiniGraphOperation(graphParam, &graphNode.operation);
125	    graphNode.inTensorIds = {3, 4};
126	    graphNode.outTensorIds = {2};
127	
128	    atb::infer::ElewiseParam addParam;
129	    addParam.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_ADD;
130	    atb::CreateOperation(addParam, &addNode.operation);
131	    addNode.inTensorIds = {0, 1};
132	    addNode.outTensorIds = {4};
133	
134	    atb::common::EventParam recordParam;
135	    recordParam.event = event;
136	    recordParam.operatorType = atb::common::EventParam::OperatorType::RECORD;
137	    atb::CreateOperation(recordParam, &recordNode.operation);
138	
139	    atb::CreateOperation(opGraph, operation);
140	}
141	
142	static void CreateGraphOperationWithRWEvent(atb::GraphParam &opGraph, atb::Operation **operation, aclrtEvent event)
143	{
144	    opGraph.inTensorNum = 2;
145	    opGraph.outTensorNum = 1;
146	    opGraph.internalTensorNum = 2;
147	    opGraph.nodes.resize(5);
148	
149	    size_t nodeId = 0;
150	    atb::Node &mulNode = opGraph.nodes.at(nodeId++);
151	    atb::Node &recordNode = opGraph.nodes.at(nodeId++);
152	    atb::Node &addNode = opGraph.nodes.at(nodeId++);
153	    atb::Node &graphNode = opGraph.nodes.at(nodeId++);
154	    atb::Node &waitNode = opGraph.nodes.at(nodeId++);
155	
156	    atb::infer::ElewiseParam mulParam;
157	    mulParam.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_MUL;
158	    atb::CreateOperation(mulParam, &mulNode.operation);
159	    mulNode.inTensorIds = {0, 1};
160	    mulNode.outTensorIds = {3};
161	
162	    atb::common::EventParam recordParam;
163	    recordParam.event = event;
164	    recordParam.operatorType = atb::common::EventParam::OperatorType::RECORD;
165	    atb::CreateOperation(recordParam, &recordNode.operation);
166	
167	    atb::GraphParam graphParam;
168	    CreateMiniGraphOperation(graphParam, &graphNode.operation);
169	    graphNode.inTensorIds = {3, 4};
170	    graphNode.outTensorIds = {2};
171	
172	    atb::infer::ElewiseParam addParam;
173	    addParam.elewiseType = atb::infer::ElewiseParam::ElewiseType::ELEWISE_ADD;
174	    atb::CreateOperation(addParam, &addNode.operation);
175	    addNode.inTensorIds = {0, 1};
176	    addNode.outTensorIds = {4};
177	
178	    atb::common::EventParam waitParam;
179	    waitParam.event = event;
180	    waitParam.operatorType = atb::common::EventParam::OperatorType::WAIT;
181	    atb::CreateOperation(waitParam, &waitNode.operation);
182	
183	    atb::CreateOperation(opGraph, operation);
184	}
185	
186	int main()
187	{
188	    aclInit(nullptr);
189	    // 设置卡号、创建stream、创建context、设置stream
190	    uint32_t deviceId = 1;
191	    aclrtSetDevice(deviceId);
192	    // 创建多个stream
193	    aclrtStream stream1 = nullptr;
194	    aclrtCreateStream(&stream1);
195	    aclrtStream stream2 = nullptr;
196	    aclrtCreateStream(&stream2);
197	
198	    aclrtEvent event;
199	    aclrtCreateEventWithFlag(&event, ACL_EVENT_SYNC);
200	
201	    atb::Context *contextWR = nullptr;
202	    atb::CreateContext(&contextWR);
203	    contextWR->SetExecuteStream(stream1);
204	    atb::Context *contextRW = nullptr;
205	    atb::CreateContext(&contextRW);
206	    contextRW->SetExecuteStream(stream2);
207	    // 创建图间同步Op
208	    // 先Wait再Record
209	    atb::Operation *operationWR = nullptr;
210	    atb::GraphParam opGraphWR;
211	    CreateGraphOperationWithWREvent(opGraphWR, &operationWR, event);
212	
213	    // 先Record再Wait
214	    atb::Operation *operationRW = nullptr;
215	    atb::GraphParam opGraphRW;
216	    CreateGraphOperationWithRWEvent(opGraphRW, &operationRW, event);
217	
218	    // 输入输出tensor准备
219	    atb::VariantPack packWR;
220	    atb::VariantPack packRW;
221	    atb::SVector<atb::TensorDesc> intensorDescs;
222	    atb::SVector<atb::TensorDesc> outtensorDescs;
223	
224	    uint32_t inTensorNum = opGraphWR.inTensorNum;
225	    uint32_t outTensorNum = opGraphWR.outTensorNum;
226	    inTensorNum = operationWR->GetInputNum();
227	    outTensorNum = operationWR->GetOutputNum();
228	
229	    packWR.inTensors.resize(inTensorNum);
230	    packRW.inTensors.resize(inTensorNum);
231	    intensorDescs.resize(inTensorNum);
232	
233	    CreateInTensorDescs(intensorDescs);
234	
235	    outtensorDescs.resize(outTensorNum);
236	    packWR.outTensors.resize(outTensorNum);
237	    packRW.outTensors.resize(outTensorNum);
238	    operationWR->InferShape(intensorDescs, outtensorDescs);
239	
240	    aclError ret = CreateInTensors(packWR.inTensors, intensorDescs);
241	    if (ret != 0) {
242	        exit(ret);
243	    }
244	    ret = CreateOutTensors(packWR.outTensors, outtensorDescs);
245	    if (ret != 0) {
246	        exit(ret);
247	    }
248	    ret = CreateInTensors(packRW.inTensors, intensorDescs);
249	    if (ret != 0) {
250	        exit(ret);
251	    }
252	    ret = CreateOutTensors(packRW.outTensors, outtensorDescs);
253	    if (ret != 0) {
254	        exit(ret);
255	    }
256	
257	    // 初始化workspace
258	    uint64_t workspaceSizeWR = 0;
259	    void *workSpaceWR = nullptr;
260	    uint64_t workspaceSizeRW = 0;
261	    void *workSpaceRW = nullptr;
262	    // 图内多流并行
263	    std::cout << "multi graph multi-stream demo start" << std::endl;
264	    // 先执行operationWR再执行operationRW
265	    operationWR->Setup(packWR, workspaceSizeWR, contextWR);
266	    operationRW->Setup(packRW, workspaceSizeRW, contextRW);
267	    if (workspaceSizeWR != 0 && workSpaceWR == nullptr) {
268	        ret = aclrtMalloc(&workSpaceWR, workspaceSizeWR, ACL_MEM_MALLOC_HUGE_FIRST);
269	        if (ret != 0) {
270	            std::cout << "alloc error!\n";
271	            exit(1);
272	        }
273	    }
274	    if (workspaceSizeRW != 0 && workSpaceRW == nullptr) {
275	        ret = aclrtMalloc(&workSpaceRW, workspaceSizeRW, ACL_MEM_MALLOC_HUGE_FIRST);
276	        if (ret != 0) {
277	            std::cout << "alloc error!\n";
278	            exit(1);
279	        }
280	    }
281	    operationWR->Execute(packWR, (uint8_t *)workSpaceWR, workspaceSizeWR, contextWR);
282	
283	    operationRW->Execute(packRW, (uint8_t *)workSpaceRW, workspaceSizeRW, contextRW);
284	
285	    // 流同步
286	    ret = aclrtSynchronizeStream(stream1);
287	    if (ret != 0) {
288	        std::cout << "sync error!";
289	        exit(1);
290	    }
291	
292	    ret = aclrtSynchronizeStream(stream2);
293	    if (ret != 0) {
